@Transactional
public OrderId placeOrder(OrderRequest req) {
    Order order = orderRepository.save(Order.from(req));
    try {
        inventoryService.reserve(req.items());
    } catch (IllegalStateException e) {
        order.markBackorder();          // đặt trước, giao sau
    }
    return order.id();
}

@Transactional
public void transfer(long from, long to, long amount) {
    ledgerRepository.save(Entry.debit(from, amount));
    auditService.record("transfer", from, to, amount);
    throw new LimitExceededException();   // RuntimeException
}

